const PLACE={akmola:['Ақмола бекінісі','1837–1838','1838 жылғы бекініске шабуыл көтерілістің алғашқы маңызды оқиғаларының бірі саналады. Нақты мерзімді бірнеше тарихи еңбектен салыстыр.'],torgai:['Торғай өңірі','1839–1845','Торғай өңірі көтерілісшілер шоғырланған маңызды аймақтардың бірі ретінде беріледі. Жер бедері мен көш жолдарының ықпалын да қарастыр.'],sozak:['Созақ және Жаңақорған','1840-жылдар','Бұл өңірлер Қоқан билігіне қарсы әрекеттермен байланысты. Бір кезеңдегі түрлі саяси күштердің ықпалын салыстыр.'],zhetysu:['Жетісу','1846','Көтерілістің соңғы кезеңі Жетісу өңірімен байланысты. Аймаққа көшуге әсер еткен жағдайларды дерекпен талда.'],last:['Соңғы шайқас бағыты','1847','Көтеріліс 1847 жылы қазіргі Қырғызстан аумағындағы соңғы шайқастан кейін аяқталды. Нақты орын мен датаны жеке дереккөзден тексер.']};
document.querySelectorAll('[data-place]').forEach(el=>el.addEventListener('click',()=>{const id=el.dataset.place,p=PLACE[id];if(!p)return;document.querySelectorAll('[data-place]').forEach(x=>{x.classList.toggle('active',x===el);const pin=x.querySelector('.pt');if(pin)pin.classList.toggle('active',x===el)});const set=(q,v)=>{const n=document.querySelector(q);if(n)n.textContent=v};set('#place-title',p[0]);set('#place-date',p[1]);set('#place-desc',p[2]);set('#place-index',`НҮКТЕ 0${Object.keys(PLACE).indexOf(id)+1} / 05`)}));
const timelineTexts=['Көтеріліс 1837 жылы басталды. 1838 жылғы Ақмола бекінісіне шабуыл алғашқы маңызды оқиғалардың бірі болды. Нақты күндерді дереккөздер арқылы тексер.','Қозғалыс кеңейіп, қазақ жасақтарын біріктіру мақсаты күшейді. 1841 жылы Кенесары Қасымұлы хан сайланды.','1842–1845 жылдары әскери әрекеттер мен келіссөздер қатар жүрді. Саяси шешімдермен байланысын да талда.','1846 жылы қозғалыс Жетісу өңірімен байланысты. Географиялық жағдайдың ықпалын дерекпен түсіндір.','1847 жылғы соңғы шайқас көтерілістің аяқталуына әкелді. Нәтиже мен тарихи маңызын бөлек тұжырымда.'];
document.querySelectorAll('[data-time]').forEach((el,i)=>el.addEventListener('click',()=>{document.querySelectorAll('[data-time]').forEach(x=>x.classList.toggle('active',x===el));const n=document.querySelector('#time-description');if(n)n.textContent=timelineTexts[i]}));
