function sessionId(){let v=localStorage.getItem('han-atlas-session');if(!v){v=crypto.randomUUID();localStorage.setItem('han-atlas-session',v)}return v}
const form=document.querySelector('#ai-form');if(form){const list=document.querySelector('#messages'),input=document.querySelector('#question'),status=document.querySelector('#ai-status'),send=document.querySelector('#send-question'),history=[];const AI_SOURCES={E1:'https://e-history.kz/kz/history-of-kazakhstan/show/8726',E2:'https://e-history.kz/media/scorm/243/192/text/text.htm',E3:'https://iie.kz/?p=25136',E4:'https://doi.org/10.1080/00905990500354137'};function renderReply(node,text){node.replaceChildren();const pattern=/\[E([1-4])\]/g;let cursor=0,match;while((match=pattern.exec(text))){node.append(document.createTextNode(text.slice(cursor,match.index)));const a=document.createElement('a'),key=`E${match[1]}`;a.href=AI_SOURCES[key];a.target='_blank';a.rel='noreferrer';a.className='ai-citation';a.textContent=`[${key}]`;node.append(a);cursor=pattern.lastIndex}node.append(document.createTextNode(text.slice(cursor)))}function bubble(text,who='assistant'){const d=document.createElement('div');d.className=`bubble ${who}`;if(who==='assistant')renderReply(d,text);else d.textContent=text;list.appendChild(d);list.scrollTop=list.scrollHeight;return d}async function ask(text){text=text.trim();if(!text||send.disabled)return;if(!window.HAN_ATLAS_AI){bubble('AI қызметі уақытша қолжетімсіз. Кейінірек қайталап көр.');status.textContent='ҚЫЗМЕТ ҚОЛЖЕТІМСІЗ';return}bubble(text,'user');input.value='';send.disabled=true;status.textContent='ЖАУАП ДАЙЫНДАЛЫП ЖАТЫР…';const pending=bubble('Ойланып жатырмын…');try{const reply=await window.HAN_ATLAS_AI.ask([...history.slice(-4),{role:'user',content:text}]);renderReply(pending,reply||'Жауап алынбады.');history.push({role:'user',content:text},{role:'assistant',content:reply||'Жауап алынбады.'});status.textContent='ТАРИХИ ЗЕРТТЕУ КӨМЕКШІСІ'}catch(e){pending.textContent=`Қазір жауап алу мүмкін болмады. ${e.message}`;status.textContent='ҚОСЫЛУ ҚАТЕСІ'}finally{send.disabled=false;input.focus()}}form.addEventListener('submit',e=>{e.preventDefault();ask(input.value)});document.querySelectorAll('[data-prompt]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.prompt)));const initialPrompt=new URLSearchParams(location.search).get('prompt');if(initialPrompt){input.value=initialPrompt;ask(initialPrompt)}}

